document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){actions[action.dataset.action]?.();return;}const restore=e.target.closest('[data-restore-window]');if(restore){const n=state.items.find(n=>n.id===restore.dataset.restoreWindow);if(n)restoreWindow(n);return;}const w=e.target.closest('[data-workspace]');if(w){switchWorkspace(w.dataset.workspace);return;}const view=e.target.closest('[data-view]');if(view){currentView=view.dataset.view;dismissMenu();render();return;}const card=e.target.closest('.card');if(card){if(!e.target.closest('button')&&performance.now()<suppressCardClickUntil)return;const n=state.items.find(n=>n.id===card.dataset.id);if(!n)return;const b=e.target.closest('[data-card-action]');if(b){if(b.dataset.cardAction==='transcribe'){transcriptionModal(n);}else if(b.dataset.cardAction==='favorite'){n.favorite=!n.favorite;touch(n);renderBoard();}else if(b.dataset.cardAction==='minimize'){setWindowState(n,'minimized');}else if(b.dataset.cardAction==='close'){setWindowState(n,'closed');persistDesk();toast('Saved. Reopen it from Saved notes.');}else{editItem(n);toggleEditorMaximize();}return;}if(e.target.matches('[data-task]')){n.tasks[Number(e.target.dataset.task)].done=e.target.checked;touch(n);render();return;}if(e.target.closest('audio')||e.target.closest('.task-line'))return;if(e.shiftKey||e.ctrlKey||e.metaKey){if(selected.has(n.id))selected.delete(n.id);else selected.add(n.id);renderBoard();}else if(e.target.closest('.card-body')){selected=new Set([n.id]);editItem(n);}}});
let drag=null,suppressCardClickUntil=0;$('#board').addEventListener('pointerdown',e=>{const card=e.target.closest('.card'),isResize=e.target.closest('.resize-handle');if(!card||listView||e.target.closest('button')||(!isResize&&!e.target.closest('.card-top')))return;if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();const n=state.items.find(n=>n.id===card.dataset.id);if(!n)return;NotaCreation.raiseItem(state,n);save();drag={n,card,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,w:n.w,h:n.h,resize:!!isResize,moved:false};card.setPointerCapture(e.pointerId);card.style.zIndex=4000;});$('#board').addEventListener('pointermove',e=>{if(!drag)return;const dx=(e.clientX-drag.startX)/zoom,dy=(e.clientY-drag.startY)/zoom;if(Math.abs(dx)+Math.abs(dy)>3)drag.moved=true;if(drag.resize){drag.n.w=Math.max(240,Math.min(900,drag.w+dx));drag.n.h=Math.max(180,Math.min(1000,drag.h+dy));drag.card.style.width=drag.n.w+'px';drag.card.style.height=drag.n.h+'px';}else{drag.n.x=Math.max(0,Math.min(4800,drag.x+dx));drag.n.y=Math.max(0,Math.min(4000000,drag.y+dy));drag.card.style.left=drag.n.x+'px';drag.card.style.top=drag.n.y+'px';}});const endDrag=()=>{if(!drag)return;if(drag.moved){suppressCardClickUntil=performance.now()+250;touch(drag.n);}drag=null;renderBoard();};$('#board').addEventListener('pointerup',endDrag);$('#board').addEventListener('pointercancel',endDrag);
$('#save-state').onclick=()=>{if(saveConflict)conflictModal();};$('#search').addEventListener('input',()=>render());$('#file-input').onchange=async e=>{await importFiles(e.target.files);e.target.value='';};$('#restore-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>80*1024*1024){toast('This backup is too large for the prototype.');return;}try{const incoming=NotaCore.validateBackup(JSON.parse(await file.text()));modal('Replace this device’s desk?',`<p>This backup contains ${incoming.workspaces.length} workspaces and ${incoming.items.length} items. Restoring replaces the current desk.</p><p class="hint">Download a backup of your current desk first if you want to keep it.</p>`,`<button class="secondary" id="restore-cancel">Cancel</button><button class="primary" id="restore-confirm">Restore this backup</button>`);$('#restore-cancel').onclick=backupModal;$('#restore-confirm').onclick=()=>{state=incoming;state.showcaseVersion=NotaShowcase.VERSION;state.settings=state.settings||{math:true,dark:false};if(!state.workspaces.some(w=>w.id===state.active))state.active=state.workspaces[0].id;currentView='all';$('#search').value='';selected.clear();closeModal();render();save();toast('Your desk has been restored.');};}catch(e){toast(e.message||'This backup could not be restored.');}};
document.addEventListener('keydown',e=>{if($('#nota-tour[open]'))return;const choice=$('.choice-overlay'),progress=$('#ai-progress-dialog:not([hidden])'),open=choice||progress||$('.modal');if(open){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();(choice?$('.choice-overlay [data-choice-cancel]'):progress?$('#ai-progress-dismiss'):$('#close-modal')).click();return;}if(e.key==='Tab'){const f=$$('button:not(:disabled),input:not(:disabled),select,textarea,[contenteditable=true]',open).filter(el=>el.getClientRects().length);if(!f.length)return;if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='n'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();actions.note();}if(e.key==='/'){e.preventDefault();$('#search').focus();}if(e.key==='Escape'){$('.desk').classList.remove('fullscreen');dismissMenu();}if(e.altKey&&/^[1-9]$/.test(e.key)){const w=state.workspaces[Number(e.key)-1];if(w){e.preventDefault();switchWorkspace(w.id);}}if(e.key==='Enter'&&e.target.matches('.card')){editItem(state.items.find(n=>n.id===e.target.dataset.id));}});
let dropDepth=0;document.addEventListener('dragenter',e=>{if(!e.dataTransfer?.types.includes('Files'))return;e.preventDefault();dropDepth++;if(!$('.drop-overlay')){const d=document.createElement('div');d.className='drop-overlay';d.textContent='Drop a little inspiration here.';document.body.append(d);}});document.addEventListener('dragover',e=>{if(e.dataTransfer?.types.includes('Files'))e.preventDefault();});document.addEventListener('dragleave',e=>{if(!e.dataTransfer?.types.includes('Files'))return;dropDepth--;if(dropDepth<=0)$('.drop-overlay')?.remove();});document.addEventListener('drop',async e=>{if(!e.dataTransfer?.files.length)return;e.preventDefault();dropDepth=0;$('.drop-overlay')?.remove();closeModal();await importFiles(e.dataTransfer.files);});document.addEventListener('visibilitychange',()=>{if(!state)return;if(document.visibilityState==='hidden')persistDesk();else{NotaPlatform.mergeNativeReminders(state.items);render();save();}});
NotaDeskMenu.configure({getState:()=>state,noteText:n=>plain(n.html||'')+' '+(n.transcript||'')+' '+(n.tasks||[]).map(t=>t.text).join(' '),onAction:action=>actions[action]?.(),onWorkspace:id=>{switchWorkspace(id);$('#desk-menu-toggle').focus({preventScroll:true});},onView:view=>{currentView=view;$('#search').value='';render();$('#desk-menu-toggle').focus({preventScroll:true});},onNote:id=>{const n=state.items.find(n=>n.id===id&&!n.deletedAt);if(n){switchWorkspace(n.workspace);editItem(n);}}});
init();
setupInstallation();
const aiRouter=new NotaAI.FreeRouter();
if(NotaPlatform.hasLocalAI)aiRouter.register({id:'android-local',kind:'local',freeTierVerified:true,paidFallback:false,tasks:Object.keys(NotaPrompts.tasks),rank:{proofread:100,polish:100,brainstorm:80,generate:80,summarize:90,organize:95},run:(request,options)=>NotaPlatform.localRequest('generate',{task:request.engineTask||request.task,prompt:request.prompt},{...options,onProgress:data=>window.dispatchEvent(new CustomEvent('nota-ai-progress',{detail:data}))})});
function setupInstallation(){window.addEventListener('nota-native-event',e=>{if(e.detail?.type==='export')toast(e.detail.ok?'File saved.':e.detail.message||'File was not saved.');});if(NotaPlatform.isAndroid){$$('[data-action=install]').forEach(b=>b.remove());return;}window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{const watch=()=>{if(reg.waiting&&navigator.serviceWorker.controller){updateWorker=reg.waiting;toast('An Nth Nota update is ready. Open Install Nth Nota to apply it.');}};watch();reg.addEventListener('updatefound',()=>reg.installing?.addEventListener('statechange',watch));}).catch(()=>{});let reloading=false;window.addEventListener('nota-apply-update',()=>{reloading=true;});navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(reloading)location.reload();});}
function installModal(){const standalone=matchMedia('(display-mode: standalone)').matches;modal('Your desk, one tap away',`<div class="assistant-intro"><h3>Take a little room with you.</h3><p>${NotaPlatform.isAndroid?'You are already using the Android app.':standalone?'Nth Nota is already running as an installed web app.':'Add Nth Nota to your home screen. Once offline preparation finishes, the editor and bundled tools can open without internet.'}</p></div><div class="setting-row"><span>Offline app files<small>Your notes stay in this browser’s device storage. Downloads and voice tools depend on your device.</small></span><span class="feature-status" id="offline-status">Checking…</span></div><p class="hint">If your browser doesn’t show an install button, use its menu and choose “Install app” or “Add to Home screen”. Android APK packaging is a separate build.</p>${updateWorker?'<p>An app update is ready. Your changes will be saved before it loads.</p>':''}`,`${updateWorker?'<button class="secondary" id="apply-update">Save and update</button>':''}${installPrompt?'<button class="primary" id="install-app">Install Nth Nota</button>':''}`);if(NotaPlatform.isAndroid)$('#offline-status').textContent='Bundled in app';else if('caches'in window)caches.keys().then(async keys=>{let ready=false;for(const key of keys.filter(k=>k.startsWith('nth-nota-shell-'))){const cache=await caches.open(key);ready=!!(await cache.match(new URL('./index.html',location.href).href))&&!!(await cache.match(new URL('./app.js',location.href).href))&&!!(await cache.match(new URL('./vendor/pdf.worker.min.mjs',location.href).href));if(ready)break;}if($('#offline-status'))$('#offline-status').textContent=ready?'Prepared':'Open online first';});else $('#offline-status').textContent='Unavailable';if($('#install-app'))$('#install-app').onclick=async()=>{await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;closeModal();};if($('#apply-update'))$('#apply-update').onclick=async()=>{closeModal();await persistDesk();if(saveConflict){conflictModal();return;}window.dispatchEvent(new Event('nota-apply-update'));updateWorker.postMessage('ACTIVATE_UPDATE');};}
window.notaOpenItem=function(id){if(!state){setTimeout(()=>window.notaOpenItem(id),150);return;}const n=state.items.find(n=>n.id===id&&!n.deletedAt);if(!n)return;switchWorkspace(n.workspace);editItem(n);};

if(NotaPlatform.cloudState().configured)aiRouter.register({id:'free-cloud',kind:'cloud',provider:'nota-gateway',freeTierVerified:true,paidFallback:false,tasks:Object.keys(NotaPrompts.tasks),rank:{proofread:40,polish:40,brainstorm:40,generate:40,summarize:40,organize:40},run:async(request,options)=>{if(!NotaPlatform.cloudState().allowed){const accepted=await cloudConsent(options.signal);if(!accepted)throw Object.assign(Error('Cloud AI is off. You can allow it in Settings; your note is unchanged.'),{code:'INVALID_REQUEST'});}return NotaPlatform.cloudRequest({task:request.engineTask||request.task,prompt:request.prompt},{...options,onProgress:data=>window.dispatchEvent(new CustomEvent('nota-ai-progress',{detail:data}))});}});

window.notaRefreshTasks=()=>{if(!state)return;NotaPlatform.mergeNativeReminders(state.items);document.querySelectorAll('[data-ti]').forEach(e=>{const n=state.items.find(n=>n.title===$('#task-title')?.value&&n.type==='task');if(n?.tasks[e.dataset.ti])e.checked=n.tasks[e.dataset.ti].done;});renderBoard();save();};
